def freeze_issued(apps, schema_editor):
    """TCN revisions issued before the list was frozen at issue: the Test Program as it is now with their changes
    (the best record there is; tcn/requirements.in_force, written out for the historical models)."""
    TcnRevision = apps.get_model("tcn", "TcnRevision")
    TcnRequirement = apps.get_model("tcn", "TcnRequirement")
    TestProgram = apps.get_model("projects", "TestProgram")
    for tcn in TcnRevision.objects.exclude(status="draft").select_related("test_run__project"):
        name = f"TCN{tcn.test_run.run_no:03d}" + (f" rev {tcn.revision}" if tcn.revision else "")
        label = f"{name}, issued {dateformat.format(timezone.localtime(tcn.issued_at), 'd-M-Y')}"
        program = TestProgram.objects.filter(project=tcn.test_run.project).first()
        changes = list(tcn.requirement_changes.order_by("order", "pk"))
        by_target = {c.program_requirement_id: c for c in changes if c.program_requirement_id}
        rows = []
        if program is not None:
            reference = " ".join(["Test Program"] + ([program.document_no] if program.document_no else [])
                                 + ([f"rev {program.revision}"] if program.revision else []))  # fmt: skip
            for requirement in program.requirements.order_by("number"):
                base = f"{reference} P{requirement.number}"
                change = by_target.get(requirement.pk)
                if change is None:
                    rows.append((requirement, requirement, None, base, False, ""))
                elif change.action == "replace":
                    rows.append((change, requirement, change, f"{label}: replaces {base}", False, change.reason))
                else:
                    rows.append((requirement, requirement, change, f"{base}; not applicable to this run per {label}",
                                 True, change.reason))  # fmt: skip
        rows += [(c, None, c, f"{label}: additional requirement", False, c.reason) for c in changes if c.action == "add"]
        for order, (values, requirement, change, source, not_applicable, reason) in enumerate(rows, start=1):
            TcnRequirement.objects.create(tcn=tcn, order=order, program_requirement=requirement, tcn_change=change,
                                          source=source[:300], not_applicable=not_applicable, reason=reason,
                                          **{name: getattr(values, name) for name in FIELDS})  # fmt: skip


